Object.assign(window.WALKBCN_UI.ca, { taTitle: "Time Attack", taDesc: "Els mateixos objectius i el mateix temps per a tothom. Tria qualsevol objectiu en qualsevol ordre: guanya qui té més punts quan s'atura el rellotge.", taTargets: "{n} objectius", taDuration: "Durada", taDemoTry: "Provar la DEMO (un sol dispositiu, sense sala)", taStart: "Sortida conjunta a:", taRules: "Punts: 100 (fàcil), 150 (mitjà), 200 (difícil) per objectiu, un cop cadascun. Una pista extra costa {h} punts en aquell objectiu. Només puntuen els objectius amb la ubicació comprovada. No hi ha recorregut fix: camina o agafa el transport públic. Quan s'acaba el temps, no hi ha més punts. Empats: més objectius trobats i, després, qui va arribar abans a la seva puntuació.", taYouDemo: "Tu (demo)", taDemoBanner: "DEMO · arribades i rivals simulats · no s'envia ni es desa res", taDemoFF: "+10 min (simulat)", taDemoEnd: "Acabar ara", taDemoRestart: "Reiniciar la demo", taDemoExit: "Sortir de la demo", taLeft: "Temps restant", taPoints: "Punts", taPos: "Posició", taPts: "pts", taLive: "Classificació en directe", taFound: "{n}/{total} trobats", taSim: "simulat", taWinner: "Guanya {name}!", taYourResult: "Has fet {p} punts amb {n} de {total} objectius.", taYourFinds: "Els teus descobriments", taAll: "Tots els objectius", taScored: "trobat ✓", taHintBtn: "Pista extra (−{h} pts)", taSimArrive: "Simular l'arribada (demo)", taSimNote: "Demo: l'arribada és simulada; la pregunta i els punts són els reals.", taGpsNote: "Comprova la ubicació quan hi siguis davant i respon. Sense comprovar la ubicació, l'objectiu no puntua.", taGpsDenied: "No s'ha permès la ubicació, així que aquest objectiu no pot puntuar. Permet la ubicació en aquest web per jugar.", taMapLabel: "Mapa dels objectius", taGot: "+{p} punts!", taTimeUp: "S'ha acabat el temps: no hi ha més punts." });
Object.assign(window.WALKBCN_UI.es, { taTitle: "Time Attack", taDesc: "Los mismos objetivos y el mismo tiempo para todos. Elige cualquier objetivo en cualquier orden: gana quien tiene más puntos cuando se para el reloj.", taTargets: "{n} objetivos", taDuration: "Duración", taDemoTry: "Probar la DEMO (un solo dispositivo, sin sala)", taStart: "Salida conjunta en:", taRules: "Puntos: 100 (fácil), 150 (medio), 200 (difícil) por objetivo, una vez cada uno. Una pista extra cuesta {h} puntos en ese objetivo. Solo puntúan los objetivos con la ubicación comprobada. No hay recorrido fijo: camina o usa el transporte público. Cuando se acaba el tiempo, no hay más puntos. Empates: más objetivos encontrados y, después, quien llegó antes a su puntuación.", taYouDemo: "Tú (demo)", taDemoBanner: "DEMO · llegadas y rivales simulados · no se envía ni se guarda nada", taDemoFF: "+10 min (simulado)", taDemoEnd: "Terminar ahora", taDemoRestart: "Reiniciar la demo", taDemoExit: "Salir de la demo", taLeft: "Tiempo restante", taPoints: "Puntos", taPos: "Posición", taPts: "pts", taLive: "Clasificación en directo", taFound: "{n}/{total} encontrados", taSim: "simulado", taWinner: "¡Gana {name}!", taYourResult: "Has hecho {p} puntos con {n} de {total} objetivos.", taYourFinds: "Tus descubrimientos", taAll: "Todos los objetivos", taScored: "encontrado ✓", taHintBtn: "Pista extra (−{h} pts)", taSimArrive: "Simular llegada (demo)", taSimNote: "Demo: la llegada es simulada; la pregunta y los puntos son los reales.", taGpsNote: "Comprueba tu ubicación cuando estés delante y responde. Sin comprobar la ubicación, el objetivo no puntúa.", taGpsDenied: "No se ha permitido la ubicación, así que este objetivo no puede puntuar. Permite la ubicación en esta web para jugar.", taMapLabel: "Mapa de los objetivos", taGot: "¡+{p} puntos!", taTimeUp: "Se ha acabado el tiempo: no hay más puntos." });
Object.assign(window.WALKBCN_UI.fr, { taTitle: "Time Attack", taDesc: "Mêmes objectifs et même temps pour tous. Choisissez n'importe quel objectif dans n'importe quel ordre : le plus de points à la fin du chrono gagne.", taTargets: "{n} objectifs", taDuration: "Durée", taDemoTry: "Essayer la DÉMO (un seul appareil, sans salon)", taStart: "Départ commun :", taRules: "Points : 100 (facile), 150 (moyen), 200 (difficile) par objectif, une fois chacun. Un indice supplémentaire coûte {h} points sur cet objectif. Seuls les objectifs avec position vérifiée rapportent des points. Pas de parcours imposé : à pied ou en transports en commun. Quand le temps est écoulé, plus de points. Égalité : plus d'objectifs trouvés, puis celui qui a atteint son score le premier.", taYouDemo: "Vous (démo)", taDemoBanner: "DÉMO · arrivées et rivaux simulés · rien n'est envoyé ni enregistré", taDemoFF: "+10 min (simulé)", taDemoEnd: "Terminer maintenant", taDemoRestart: "Relancer la démo", taDemoExit: "Quitter la démo", taLeft: "Temps restant", taPoints: "Points", taPos: "Position", taPts: "pts", taLive: "Classement en direct", taFound: "{n}/{total} trouvés", taSim: "simulé", taWinner: "{name} gagne !", taYourResult: "Vous avez marqué {p} points avec {n} objectifs sur {total}.", taYourFinds: "Vos découvertes", taAll: "Tous les objectifs", taScored: "trouvé ✓", taHintBtn: "Indice supplémentaire (−{h} pts)", taSimArrive: "Simuler l'arrivée (démo)", taSimNote: "Démo : l'arrivée est simulée ; la question et les points sont les vrais.", taGpsNote: "Vérifiez votre position une fois devant, puis répondez. Sans vérification de position, l'objectif ne rapporte rien.", taGpsDenied: "La position n'est pas autorisée : cet objectif ne peut pas rapporter de points. Autorisez la position sur ce site pour jouer.", taMapLabel: "Carte des objectifs", taGot: "+{p} points !", taTimeUp: "Temps écoulé : plus de points." });
Object.assign(window.WALKBCN_UI.de, { taTitle: "Time Attack", taDesc: "Gleiche Ziele und gleiche Zeit für alle. Wähle jedes Ziel in beliebiger Reihenfolge: Wer bei Ablauf der Zeit die meisten Punkte hat, gewinnt.", taTargets: "{n} Ziele", taDuration: "Dauer", taDemoTry: "DEMO testen (ein Gerät, kein Raum)", taStart: "Gemeinsamer Start:", taRules: "Punkte: 100 (leicht), 150 (mittel), 200 (schwer) pro Ziel, jedes nur einmal. Ein zusätzlicher Hinweis kostet {h} Punkte bei diesem Ziel. Nur Ziele mit geprüftem Standort zählen. Keine feste Route: zu Fuß oder mit öffentlichen Verkehrsmitteln. Nach Ablauf der Zeit gibt es keine Punkte mehr. Gleichstand: mehr gefundene Ziele, dann wer seine Punktzahl zuerst erreicht hat.", taYouDemo: "Du (Demo)", taDemoBanner: "DEMO · Ankunft und Gegner simuliert · nichts wird gesendet oder gespeichert", taDemoFF: "+10 Min. (simuliert)", taDemoEnd: "Jetzt beenden", taDemoRestart: "Demo neu starten", taDemoExit: "Demo verlassen", taLeft: "Restzeit", taPoints: "Punkte", taPos: "Platz", taPts: "Pkt.", taLive: "Live-Rangliste", taFound: "{n}/{total} gefunden", taSim: "simuliert", taWinner: "{name} gewinnt!", taYourResult: "Du hast {p} Punkte mit {n} von {total} Zielen.", taYourFinds: "Deine Entdeckungen", taAll: "Alle Ziele", taScored: "gefunden ✓", taHintBtn: "Zusätzlicher Hinweis (−{h} Pkt.)", taSimArrive: "Ankunft simulieren (Demo)", taSimNote: "Demo: Die Ankunft ist simuliert; Frage und Punkte sind echt.", taGpsNote: "Prüfe deinen Standort, wenn du davorstehst, und antworte dann. Ohne Standortprüfung zählt das Ziel nicht.", taGpsDenied: "Der Standortzugriff ist nicht erlaubt, daher kann dieses Ziel nicht zählen. Erlaube den Standort für diese Seite, um zu spielen.", taMapLabel: "Karte der Ziele", taGot: "+{p} Punkte!", taTimeUp: "Die Zeit ist um: keine Punkte mehr." });
Object.assign(window.WALKBCN_UI.it, { taTitle: "Time Attack", taDesc: "Stessi obiettivi e stesso tempo per tutti. Scegli qualsiasi obiettivo in qualsiasi ordine: vince chi ha più punti allo scadere del tempo.", taTargets: "{n} obiettivi", taDuration: "Durata", taDemoTry: "Prova la DEMO (un solo dispositivo, senza stanza)", taStart: "Partenza comune:", taRules: "Punti: 100 (facile), 150 (medio), 200 (difficile) per obiettivo, una volta ciascuno. Un indizio extra costa {h} punti su quell'obiettivo. Contano solo gli obiettivi con la posizione verificata. Nessun percorso fisso: a piedi o con i mezzi pubblici. Allo scadere del tempo, niente più punti. Parità: più obiettivi trovati e poi chi ha raggiunto prima il suo punteggio.", taYouDemo: "Tu (demo)", taDemoBanner: "DEMO · arrivi e avversari simulati · non si invia né si salva nulla", taDemoFF: "+10 min (simulato)", taDemoEnd: "Termina ora", taDemoRestart: "Ricomincia la demo", taDemoExit: "Esci dalla demo", taLeft: "Tempo rimasto", taPoints: "Punti", taPos: "Posizione", taPts: "pt", taLive: "Classifica in diretta", taFound: "{n}/{total} trovati", taSim: "simulato", taWinner: "Vince {name}!", taYourResult: "Hai fatto {p} punti con {n} obiettivi su {total}.", taYourFinds: "Le tue scoperte", taAll: "Tutti gli obiettivi", taScored: "trovato ✓", taHintBtn: "Indizio extra (−{h} pt)", taSimArrive: "Simula l'arrivo (demo)", taSimNote: "Demo: l'arrivo è simulato; domanda e punti sono quelli veri.", taGpsNote: "Verifica la posizione quando ci sei davanti, poi rispondi. Senza verifica della posizione l'obiettivo non conta.", taGpsDenied: "La posizione non è consentita, quindi questo obiettivo non può fare punti. Consenti la posizione per questo sito per giocare.", taMapLabel: "Mappa degli obiettivi", taGot: "+{p} punti!", taTimeUp: "Tempo scaduto: niente più punti." });
Object.assign(window.WALKBCN_UI.zh, { taTitle: "限时挑战", taDesc: "所有人的目标和时间相同。按任意顺序选择任意目标：时间结束时得分最高者获胜。", taTargets: "{n} 个目标", taDuration: "时长", taDemoTry: "试玩演示（单台设备，无需房间）", taStart: "共同出发点：", taRules: "得分：每个目标 100（易）、150（中）、200（难），每个只计一次。在某个目标上使用额外线索扣 {h} 分。只有核验了位置的目标才计分。没有固定路线：可步行或乘公共交通。时间一到便不再计分。平分时：找到目标更多者胜，再看谁先达到最终得分。", taYouDemo: "你（演示）", taDemoBanner: "演示 · 到达和对手均为模拟 · 不发送也不保存任何内容", taDemoFF: "+10 分钟（模拟）", taDemoEnd: "立即结束", taDemoRestart: "重新开始演示", taDemoExit: "退出演示", taLeft: "剩余时间", taPoints: "得分", taPos: "名次", taPts: "分", taLive: "实时排名", taFound: "已找到 {n}/{total}", taSim: "模拟", taWinner: "{name} 获胜！", taYourResult: "你在 {total} 个目标中找到 {n} 个，得 {p} 分。", taYourFinds: "你的发现", taAll: "全部目标", taScored: "已找到 ✓", taHintBtn: "额外线索（−{h} 分）", taSimArrive: "模拟到达（演示）", taSimNote: "演示：到达是模拟的；问题和得分都是真实的。", taGpsNote: "到了目标前面再核验位置，然后回答。未核验位置的目标不计分。", taGpsDenied: "未允许访问位置，因此该目标无法计分。请允许本网站使用位置后再玩。", taMapLabel: "目标地图", taGot: "+{p} 分！", taTimeUp: "时间到：不再计分。" });
