Object.assign(window.WALKBCN_UI.en, { bbTitle: "Bingo Battle", bbDesc: "Same 3 × 3 board for everyone. Find the places in any order: the first to complete a line wins.", bbRules: "Rules: any square, any order, each once. A square counts only with a location check and the right answer. The first player confirmed with a full row, column or diagonal wins. After {m} minutes without a line, the game ends with no winner. Take any route; walk, don't run.", bbDemoBanner: "DEMO · simulated arrivals and rivals · nothing is sent or saved", bbAdvance: "Advance rivals (simulated)", bbRivalClose: "Rival close to a line", bbSquares: "Squares", bbForLine: "To a line", bbGameTime: "Game time", bbRivals: "Players (squares found)", bbLineWord: "line", bbOneAway: "1 away from a line!", bbNearTag: "1 for line", bbYouWon: "Bingo! You won!", bbNoWinner: "Time's up: nobody completed a line.", bbWinLine: "Winning line: {list}", bbGameTimeIs: "Game time {t}", bbYourSquares: "your squares: {n}/9", bbDone: "Square done ✓", bbWouldWin: "this square completes a line", bbGpsNote: "Check your location when you're there, then answer. Without a location check the square doesn't count.", bbGpsDenied: "Location access isn't allowed, so this square can't count. Allow location for this site to play.", bbPick: "Tap a square to see where it is and its question.", bbLineNow: "Line! ★", bbOver: "The game has already ended." });
Object.assign(window.WALKBCN_UI.ca, { bbTitle: "Bingo Battle", bbDesc: "El mateix tauler de 3 × 3 per a tothom. Troba els llocs en qualsevol ordre: guanya qui completa primer una línia.", bbRules: "Normes: qualsevol casella, en qualsevol ordre, un cop cadascuna. Una casella només compta amb la ubicació comprovada i la resposta correcta. Guanya el primer jugador confirmat amb una fila, columna o diagonal completa. Si en {m} minuts ningú fa línia, la partida acaba sense guanyador. Ves per on vulguis; camina, no corris.", bbDemoBanner: "DEMO · arribades i rivals simulats · no s'envia ni es desa res", bbAdvance: "Avançar els rivals (simulat)", bbRivalClose: "Rival a prop de fer línia", bbSquares: "Caselles", bbForLine: "Per a línia", bbGameTime: "Durada", bbRivals: "Jugadors (caselles trobades)", bbLineWord: "línia", bbOneAway: "a 1 de fer línia!", bbNearTag: "1 per línia", bbYouWon: "Bingo! Has guanyat!", bbNoWinner: "S'ha acabat el temps: ningú ha completat una línia.", bbWinLine: "Línia guanyadora: {list}", bbGameTimeIs: "Durada {t}", bbYourSquares: "les teves caselles: {n}/9", bbDone: "Casella feta ✓", bbWouldWin: "aquesta casella completa una línia", bbGpsNote: "Comprova la ubicació quan hi siguis i respon. Sense comprovar la ubicació, la casella no compta.", bbGpsDenied: "No s'ha permès la ubicació, així que aquesta casella no pot comptar. Permet la ubicació en aquest web per jugar.", bbPick: "Toca una casella per veure on és i la seva pregunta.", bbLineNow: "Línia! ★", bbOver: "La partida ja ha acabat." });
Object.assign(window.WALKBCN_UI.es, { bbTitle: "Bingo Battle", bbDesc: "El mismo tablero de 3 × 3 para todos. Encuentra los lugares en cualquier orden: gana quien completa primero una línea.", bbRules: "Reglas: cualquier casilla, en cualquier orden, una vez cada una. Una casilla solo cuenta con la ubicación comprobada y la respuesta correcta. Gana el primer jugador confirmado con una fila, columna o diagonal completa. Si en {m} minutos nadie hace línea, la partida termina sin ganador. Ve por donde quieras; camina, no corras.", bbDemoBanner: "DEMO · llegadas y rivales simulados · no se envía ni se guarda nada", bbAdvance: "Avanzar a los rivales (simulado)", bbRivalClose: "Rival cerca de hacer línea", bbSquares: "Casillas", bbForLine: "Para línea", bbGameTime: "Duración", bbRivals: "Jugadores (casillas encontradas)", bbLineWord: "línea", bbOneAway: "¡a 1 de hacer línea!", bbNearTag: "1 para línea", bbYouWon: "¡Bingo! ¡Has ganado!", bbNoWinner: "Se acabó el tiempo: nadie ha completado una línea.", bbWinLine: "Línea ganadora: {list}", bbGameTimeIs: "Duración {t}", bbYourSquares: "tus casillas: {n}/9", bbDone: "Casilla hecha ✓", bbWouldWin: "esta casilla completa una línea", bbGpsNote: "Comprueba tu ubicación cuando estés allí y responde. Sin comprobar la ubicación, la casilla no cuenta.", bbGpsDenied: "No se ha permitido la ubicación, así que esta casilla no puede contar. Permite la ubicación en esta web para jugar.", bbPick: "Toca una casilla para ver dónde está y su pregunta.", bbLineNow: "¡Línea! ★", bbOver: "La partida ya ha terminado." });
Object.assign(window.WALKBCN_UI.fr, { bbTitle: "Bingo Battle", bbDesc: "La même grille de 3 × 3 pour tous. Trouvez les lieux dans n'importe quel ordre : le premier à compléter une ligne gagne.", bbRules: "Règles : n'importe quelle case, dans n'importe quel ordre, une fois chacune. Une case ne compte qu'avec la position vérifiée et la bonne réponse. Le premier joueur confirmé avec une ligne, une colonne ou une diagonale complète gagne. Sans ligne au bout de {m} minutes, la partie s'arrête sans gagnant. Prenez le chemin que vous voulez ; marchez, ne courez pas.", bbDemoBanner: "DÉMO · arrivées et rivaux simulés · rien n'est envoyé ni enregistré", bbAdvance: "Faire avancer les rivaux (simulé)", bbRivalClose: "Un rival près de la ligne", bbSquares: "Cases", bbForLine: "Pour une ligne", bbGameTime: "Durée", bbRivals: "Joueurs (cases trouvées)", bbLineWord: "ligne", bbOneAway: "à 1 case de la ligne !", bbNearTag: "1 pour la ligne", bbYouWon: "Bingo ! Vous avez gagné !", bbNoWinner: "Temps écoulé : personne n'a complété de ligne.", bbWinLine: "Ligne gagnante : {list}", bbGameTimeIs: "Durée {t}", bbYourSquares: "vos cases : {n}/9", bbDone: "Case validée ✓", bbWouldWin: "cette case complète une ligne", bbGpsNote: "Vérifiez votre position une fois sur place, puis répondez. Sans vérification de position, la case ne compte pas.", bbGpsDenied: "La position n'est pas autorisée : cette case ne peut pas compter. Autorisez la position sur ce site pour jouer.", bbPick: "Touchez une case pour voir où elle se trouve et sa question.", bbLineNow: "Ligne ! ★", bbOver: "La partie est déjà terminée." });
Object.assign(window.WALKBCN_UI.de, { bbTitle: "Bingo Battle", bbDesc: "Dasselbe 3 × 3-Feld für alle. Finde die Orte in beliebiger Reihenfolge: Wer zuerst eine Reihe voll hat, gewinnt.", bbRules: "Regeln: jedes Feld, in beliebiger Reihenfolge, jedes einmal. Ein Feld zählt nur mit geprüftem Standort und richtiger Antwort. Es gewinnt, wer zuerst bestätigt eine volle Zeile, Spalte oder Diagonale hat. Ohne Reihe nach {m} Minuten endet das Spiel ohne Sieger. Nimm jeden Weg; geh, renn nicht.", bbDemoBanner: "DEMO · Ankunft und Gegner simuliert · nichts wird gesendet oder gespeichert", bbAdvance: "Gegner vorrücken (simuliert)", bbRivalClose: "Gegner kurz vor der Reihe", bbSquares: "Felder", bbForLine: "Bis zur Reihe", bbGameTime: "Spieldauer", bbRivals: "Spieler (gefundene Felder)", bbLineWord: "Reihe", bbOneAway: "1 Feld vor der Reihe!", bbNearTag: "1 zur Reihe", bbYouWon: "Bingo! Du hast gewonnen!", bbNoWinner: "Die Zeit ist um: Niemand hat eine Reihe geschafft.", bbWinLine: "Siegerreihe: {list}", bbGameTimeIs: "Spieldauer {t}", bbYourSquares: "deine Felder: {n}/9", bbDone: "Feld geschafft ✓", bbWouldWin: "dieses Feld vervollständigt eine Reihe", bbGpsNote: "Prüfe deinen Standort vor Ort und antworte dann. Ohne Standortprüfung zählt das Feld nicht.", bbGpsDenied: "Der Standortzugriff ist nicht erlaubt, daher kann dieses Feld nicht zählen. Erlaube den Standort für diese Seite, um zu spielen.", bbPick: "Tippe auf ein Feld, um zu sehen, wo es ist und welche Frage es hat.", bbLineNow: "Reihe! ★", bbOver: "Das Spiel ist schon vorbei." });
Object.assign(window.WALKBCN_UI.it, { bbTitle: "Bingo Battle", bbDesc: "La stessa tabella 3 × 3 per tutti. Trova i luoghi in qualsiasi ordine: vince chi completa per primo una linea.", bbRules: "Regole: qualsiasi casella, in qualsiasi ordine, una volta ciascuna. Una casella conta solo con la posizione verificata e la risposta giusta. Vince il primo giocatore confermato con una riga, colonna o diagonale completa. Se in {m} minuti nessuno fa linea, la partita finisce senza vincitore. Scegli la strada che vuoi; cammina, non correre.", bbDemoBanner: "DEMO · arrivi e avversari simulati · non si invia né si salva nulla", bbAdvance: "Fai avanzare gli avversari (simulato)", bbRivalClose: "Avversario vicino alla linea", bbSquares: "Caselle", bbForLine: "Per la linea", bbGameTime: "Durata", bbRivals: "Giocatori (caselle trovate)", bbLineWord: "linea", bbOneAway: "a 1 dalla linea!", bbNearTag: "1 per linea", bbYouWon: "Bingo! Hai vinto!", bbNoWinner: "Tempo scaduto: nessuno ha completato una linea.", bbWinLine: "Linea vincente: {list}", bbGameTimeIs: "Durata {t}", bbYourSquares: "le tue caselle: {n}/9", bbDone: "Casella fatta ✓", bbWouldWin: "questa casella completa una linea", bbGpsNote: "Verifica la posizione quando sei lì, poi rispondi. Senza verifica della posizione la casella non conta.", bbGpsDenied: "La posizione non è consentita, quindi questa casella non può contare. Consenti la posizione per questo sito per giocare.", bbPick: "Tocca una casella per vedere dov'è e la sua domanda.", bbLineNow: "Linea! ★", bbOver: "La partita è già finita." });
Object.assign(window.WALKBCN_UI.zh, { bbTitle: "宾果对战", bbDesc: "所有人使用相同的 3 × 3 方格。按任意顺序寻找地点：最先连成一条线者获胜。", bbRules: "规则：任意格子、任意顺序，每格只计一次。只有核验了位置且答对，格子才算数。最先被确认连成一整行、一整列或一条对角线的玩家获胜。若 {m} 分钟内无人连线，游戏结束且无人获胜。路线随你选；请步行，不要奔跑。", bbDemoBanner: "演示 · 到达和对手均为模拟 · 不发送也不保存任何内容", bbAdvance: "推进对手（模拟）", bbRivalClose: "对手即将连线", bbSquares: "格子", bbForLine: "距连线", bbGameTime: "用时", bbRivals: "玩家（已找到的格子）", bbLineWord: "连线", bbOneAway: "只差 1 格连线！", bbNearTag: "差1连线", bbYouWon: "宾果！你赢了！", bbNoWinner: "时间到：无人连成一条线。", bbWinLine: "获胜连线：{list}", bbGameTimeIs: "用时 {t}", bbYourSquares: "你的格子：{n}/9", bbDone: "格子完成 ✓", bbWouldWin: "这一格可以完成一条线", bbGpsNote: "到达现场后核验位置，再回答。未核验位置的格子不算数。", bbGpsDenied: "未允许访问位置，因此这一格无法计数。请允许本网站使用位置后再玩。", bbPick: "点一个格子，查看它的位置和问题。", bbLineNow: "连线！★", bbOver: "游戏已经结束。" });
