Object.assign(window.WALKBCN_UI.en, { mpCooperative: "Cooperative", mpCompHint: "Everyone plays for themselves: the fastest or highest score wins.", smDesc: "Shared Mystery: play as a team. Each phone gets different clues, so you'll need to talk, share and look closely to solve a real piece of Barcelona's history together.", smPick: "Choose an adventure", smMeta: "{n} places + final deduction · about {m} min", smDemoPlayers: "Players in the demo", smDemoBanner: "DEMO · simulated teammates and arrivals · nothing is sent or saved", smViewAs: "See the game as:", smAllShare: "Everyone shares their clues (simulated)", smFinalStep: "Final deduction", smTeam: "Team", smLeft: "left", smNotebook: "Team notebook", smQ: "The team's question", smQHint: "Anyone can answer for the team. Compare your clues first: one alone isn't enough.", smEndedUnsolved: "The investigation ended before the mystery was solved.", smFictionTag: "Story frame: fiction · Places and facts: real", smRules: "How it works: at each place every phone shows different clues. Walk together, confirm you've arrived (one phone is enough), read your clues aloud or put them on the team board, and answer as a team. No clock and no ranking: you win together.", smBegin: "Start the investigation", smNew: "New in your notebook:", smStep: "Place {n} of {total}", smArrive: "We're here: check location", smArriveManual: "We're here (without a location check)", smSimNote: "Demo: the arrival is simulated; clues, questions and answers are the real ones.", smGpsNote: "One location check on any phone counts for the whole team. Only “arrived” is sent, never your position.", smYourClues: "Your clues", smNoClues: "No clue for you at this place. Read the question aloud, look around and help the team put the pieces together.", smOffline: "{name} is offline: show their clues here", smBoard: "Team board", smBoardEmpty: "Nothing shared yet. Read your clues aloud, or tap “Share with the team”.", smSharedBy: "shared by {name}", smShared: "on the team board", smShare: "Share with the team", smTakenFrom: "{name}'s clue", smKind_history: "History", smKind_visual: "Look for", smKind_architecture: "Architecture", smKind_interpretation: "Interpretation", smArrivedGps: "Arrived · location checked", smArrivedSim: "Arrived · simulated (demo)", smArrivedManual: "Arrived · confirmed without a location check", smGpsDenied: "Location access isn't allowed. You can still confirm you're here without a location check.", smWrong: "Not quite. Compare your clues: you need more than one to get it.", smRight: "Solved! ✓", smSolvedTitle: "Mystery solved", smSolution: "The solution", smConnect: "How your clues fit together", smStory: "The full story", smRestart: "Start again", smFacts: "Did you know?", smFiction: "The note that opens the adventure is fiction. Places, dates and facts are real and come from the sources below.", smPhotos: "Photos (Wikimedia Commons)", smListen: "Listen", smPause: "Pause", smRec: "Recorded narration.", smVoice: "Read by your device's voice (no recording yet).", smNoVoice: "This device can't read aloud: the full text is below." });
Object.assign(window.WALKBCN_UI.ca, { mpCooperative: "Cooperatiu", mpCompHint: "Cadascú juga per si mateix: guanya qui és més ràpid o fa més punts.", smDesc: "Shared Mystery: jugueu en equip. Cada mòbil rep pistes diferents, així que haureu de parlar, compartir i observar per resoldre junts un fragment real de la història de Barcelona.", smPick: "Tria una aventura", smMeta: "{n} llocs + deducció final · uns {m} min", smDemoPlayers: "Jugadors a la demo", smDemoBanner: "DEMO · companys i arribades simulats · no s'envia ni es desa res", smViewAs: "Veure la partida com:", smAllShare: "Tothom comparteix les pistes (simulat)", smFinalStep: "Deducció final", smTeam: "Equip", smLeft: "ha marxat", smNotebook: "Llibreta de l'equip", smQ: "La pregunta de l'equip", smQHint: "Qualsevol pot respondre per l'equip. Primer compareu les pistes: amb una sola no n'hi ha prou.", smEndedUnsolved: "La investigació ha acabat abans de resoldre el misteri.", smFictionTag: "Marc narratiu: ficció · Llocs i fets: reals", smRules: "Com funciona: a cada lloc, cada mòbil mostra pistes diferents. Camineu junts, confirmeu que hi heu arribat (n'hi ha prou amb un mòbil), llegiu les pistes en veu alta o poseu-les al tauler de l'equip i responeu en equip. Sense rellotge ni classificació: guanyeu junts.", smBegin: "Començar la investigació", smNew: "Nou a la llibreta:", smStep: "Lloc {n} de {total}", smArrive: "Ja hi som: comprovar la ubicació", smArriveManual: "Ja hi som (sense comprovar la ubicació)", smSimNote: "Demo: l'arribada és simulada; les pistes, preguntes i respostes són les reals.", smGpsNote: "Una comprovació d'ubicació en qualsevol mòbil val per a tot l'equip. Només s'envia «hem arribat», mai la vostra posició.", smYourClues: "Les teves pistes", smNoClues: "En aquest lloc no tens cap pista. Llegeix la pregunta en veu alta, mira al voltant i ajuda l'equip a encaixar les peces.", smOffline: "{name} està desconnectat: mostra aquí les seves pistes", smBoard: "Tauler de l'equip", smBoardEmpty: "Encara no s'ha compartit res. Llegiu les pistes en veu alta o toqueu «Compartir amb l'equip».", smSharedBy: "compartida per {name}", smShared: "al tauler de l'equip", smShare: "Compartir amb l'equip", smTakenFrom: "Pista de {name}", smKind_history: "Història", smKind_visual: "Busca", smKind_architecture: "Arquitectura", smKind_interpretation: "Interpretació", smArrivedGps: "Hi heu arribat · ubicació comprovada", smArrivedSim: "Hi heu arribat · simulat (demo)", smArrivedManual: "Hi heu arribat · confirmat sense comprovar la ubicació", smGpsDenied: "No s'ha permès la ubicació. Podeu confirmar igualment que hi sou sense comprovar-la.", smWrong: "No ben bé. Compareu les pistes: en necessiteu més d'una.", smRight: "Resolt! ✓", smSolvedTitle: "Misteri resolt", smSolution: "La solució", smConnect: "Com encaixen les vostres pistes", smStory: "La història completa", smRestart: "Tornar a començar", smFacts: "Sabíeu que…?", smFiction: "La nota que obre l'aventura és ficció. Els llocs, les dates i els fets són reals i surten de les fonts de sota.", smPhotos: "Fotos (Wikimedia Commons)", smListen: "Escoltar", smPause: "Pausa", smRec: "Narració gravada.", smVoice: "Llegit per la veu del dispositiu (encara no hi ha gravació).", smNoVoice: "Aquest dispositiu no pot llegir en veu alta: el text complet és a sota." });
Object.assign(window.WALKBCN_UI.es, { mpCooperative: "Cooperativo", mpCompHint: "Cada uno juega por sí mismo: gana quien es más rápido o suma más puntos.", smDesc: "Shared Mystery: jugad en equipo. Cada móvil recibe pistas diferentes, así que tendréis que hablar, compartir y observar para resolver juntos un fragmento real de la historia de Barcelona.", smPick: "Elige una aventura", smMeta: "{n} lugares + deducción final · unos {m} min", smDemoPlayers: "Jugadores en la demo", smDemoBanner: "DEMO · compañeros y llegadas simulados · no se envía ni se guarda nada", smViewAs: "Ver la partida como:", smAllShare: "Todos comparten sus pistas (simulado)", smFinalStep: "Deducción final", smTeam: "Equipo", smLeft: "se ha ido", smNotebook: "Cuaderno del equipo", smQ: "La pregunta del equipo", smQHint: "Cualquiera puede responder por el equipo. Comparad antes las pistas: con una sola no basta.", smEndedUnsolved: "La investigación terminó antes de resolver el misterio.", smFictionTag: "Marco narrativo: ficción · Lugares y hechos: reales", smRules: "Cómo funciona: en cada lugar, cada móvil muestra pistas diferentes. Caminad juntos, confirmad que habéis llegado (basta con un móvil), leed las pistas en voz alta o ponedlas en el tablero del equipo y responded en equipo. Sin reloj ni clasificación: ganáis juntos.", smBegin: "Empezar la investigación", smNew: "Nuevo en el cuaderno:", smStep: "Lugar {n} de {total}", smArrive: "Ya estamos: comprobar ubicación", smArriveManual: "Ya estamos (sin comprobar la ubicación)", smSimNote: "Demo: la llegada es simulada; las pistas, preguntas y respuestas son las reales.", smGpsNote: "Una comprobación de ubicación en cualquier móvil vale para todo el equipo. Solo se envía «hemos llegado», nunca vuestra posición.", smYourClues: "Tus pistas", smNoClues: "En este lugar no tienes pista. Lee la pregunta en voz alta, mira alrededor y ayuda al equipo a encajar las piezas.", smOffline: "{name} está desconectado: mostrar aquí sus pistas", smBoard: "Tablero del equipo", smBoardEmpty: "Aún no se ha compartido nada. Leed las pistas en voz alta o tocad «Compartir con el equipo».", smSharedBy: "compartida por {name}", smShared: "en el tablero del equipo", smShare: "Compartir con el equipo", smTakenFrom: "Pista de {name}", smKind_history: "Historia", smKind_visual: "Busca", smKind_architecture: "Arquitectura", smKind_interpretation: "Interpretación", smArrivedGps: "Habéis llegado · ubicación comprobada", smArrivedSim: "Habéis llegado · simulado (demo)", smArrivedManual: "Habéis llegado · confirmado sin comprobar la ubicación", smGpsDenied: "No se ha permitido la ubicación. Podéis confirmar igualmente que estáis aquí sin comprobarla.", smWrong: "No exactamente. Comparad las pistas: necesitáis más de una.", smRight: "¡Resuelto! ✓", smSolvedTitle: "Misterio resuelto", smSolution: "La solución", smConnect: "Cómo encajan vuestras pistas", smStory: "La historia completa", smRestart: "Volver a empezar", smFacts: "¿Sabíais que…?", smFiction: "La nota que abre la aventura es ficción. Los lugares, las fechas y los hechos son reales y proceden de las fuentes de abajo.", smPhotos: "Fotos (Wikimedia Commons)", smListen: "Escuchar", smPause: "Pausa", smRec: "Narración grabada.", smVoice: "Leído por la voz del dispositivo (aún no hay grabación).", smNoVoice: "Este dispositivo no puede leer en voz alta: el texto completo está abajo." });
Object.assign(window.WALKBCN_UI.fr, { mpCooperative: "Coopératif", mpCompHint: "Chacun joue pour soi : le plus rapide ou le meilleur score gagne.", smDesc: "Shared Mystery : jouez en équipe. Chaque téléphone reçoit des indices différents : il faudra parler, partager et bien observer pour résoudre ensemble un vrai pan de l'histoire de Barcelone.", smPick: "Choisissez une aventure", smMeta: "{n} lieux + déduction finale · environ {m} min", smDemoPlayers: "Joueurs dans la démo", smDemoBanner: "DÉMO · coéquipiers et arrivées simulés · rien n'est envoyé ni enregistré", smViewAs: "Voir la partie comme :", smAllShare: "Tout le monde partage ses indices (simulé)", smFinalStep: "Déduction finale", smTeam: "Équipe", smLeft: "est parti", smNotebook: "Carnet de l'équipe", smQ: "La question de l'équipe", smQHint: "N'importe qui peut répondre pour l'équipe. Comparez d'abord vos indices : un seul ne suffit pas.", smEndedUnsolved: "L'enquête s'est terminée avant que le mystère soit résolu.", smFictionTag: "Cadre du récit : fiction · Lieux et faits : réels", smRules: "Comment ça marche : à chaque lieu, chaque téléphone affiche des indices différents. Marchez ensemble, confirmez votre arrivée (un téléphone suffit), lisez vos indices à voix haute ou placez-les sur le tableau de l'équipe, et répondez en équipe. Ni chrono ni classement : vous gagnez ensemble.", smBegin: "Commencer l'enquête", smNew: "Nouveau dans le carnet :", smStep: "Lieu {n} sur {total}", smArrive: "Nous y sommes : vérifier la position", smArriveManual: "Nous y sommes (sans vérifier la position)", smSimNote: "Démo : l'arrivée est simulée ; indices, questions et réponses sont les vrais.", smGpsNote: "Une vérification de position sur n'importe quel téléphone vaut pour toute l'équipe. Seul « arrivés » est envoyé, jamais votre position.", smYourClues: "Vos indices", smNoClues: "Pas d'indice pour vous ici. Lisez la question à voix haute, regardez autour de vous et aidez l'équipe à assembler les pièces.", smOffline: "{name} est hors ligne : afficher ses indices ici", smBoard: "Tableau de l'équipe", smBoardEmpty: "Rien n'a encore été partagé. Lisez vos indices à voix haute ou touchez « Partager avec l'équipe ».", smSharedBy: "partagé par {name}", smShared: "sur le tableau de l'équipe", smShare: "Partager avec l'équipe", smTakenFrom: "Indice de {name}", smKind_history: "Histoire", smKind_visual: "À chercher", smKind_architecture: "Architecture", smKind_interpretation: "Interprétation", smArrivedGps: "Arrivés · position vérifiée", smArrivedSim: "Arrivés · simulé (démo)", smArrivedManual: "Arrivés · confirmé sans vérifier la position", smGpsDenied: "La position n'est pas autorisée. Vous pouvez quand même confirmer votre arrivée sans vérification.", smWrong: "Pas tout à fait. Comparez vos indices : il en faut plus d'un.", smRight: "Résolu ! ✓", smSolvedTitle: "Mystère résolu", smSolution: "La solution", smConnect: "Comment vos indices s'assemblent", smStory: "Toute l'histoire", smRestart: "Recommencer", smFacts: "Le saviez-vous ?", smFiction: "La note qui ouvre l'aventure est une fiction. Les lieux, les dates et les faits sont réels et viennent des sources ci-dessous.", smPhotos: "Photos (Wikimedia Commons)", smListen: "Écouter", smPause: "Pause", smRec: "Narration enregistrée.", smVoice: "Lu par la voix de l'appareil (pas encore d'enregistrement).", smNoVoice: "Cet appareil ne peut pas lire à voix haute : le texte complet est ci-dessous." });
Object.assign(window.WALKBCN_UI.de, { mpCooperative: "Kooperativ", mpCompHint: "Jeder spielt für sich: Wer am schnellsten ist oder die meisten Punkte holt, gewinnt.", smDesc: "Shared Mystery: Spielt als Team. Jedes Handy bekommt andere Hinweise – ihr müsst reden, teilen und genau hinsehen, um gemeinsam ein echtes Stück Geschichte Barcelonas zu lösen.", smPick: "Wähle ein Abenteuer", smMeta: "{n} Orte + Schlussfolgerung · etwa {m} Min.", smDemoPlayers: "Spieler in der Demo", smDemoBanner: "DEMO · Mitspieler und Ankunft simuliert · nichts wird gesendet oder gespeichert", smViewAs: "Spiel ansehen als:", smAllShare: "Alle teilen ihre Hinweise (simuliert)", smFinalStep: "Schlussfolgerung", smTeam: "Team", smLeft: "ausgestiegen", smNotebook: "Notizbuch des Teams", smQ: "Die Frage an das Team", smQHint: "Jeder kann für das Team antworten. Vergleicht zuerst eure Hinweise: Einer allein reicht nicht.", smEndedUnsolved: "Die Ermittlung endete, bevor das Rätsel gelöst war.", smFictionTag: "Rahmenhandlung: Fiktion · Orte und Fakten: echt", smRules: "So geht's: An jedem Ort zeigt jedes Handy andere Hinweise. Geht zusammen, bestätigt die Ankunft (ein Handy genügt), lest eure Hinweise laut vor oder legt sie auf die Team-Tafel und antwortet als Team. Keine Uhr, keine Rangliste: Ihr gewinnt gemeinsam.", smBegin: "Ermittlung starten", smNew: "Neu im Notizbuch:", smStep: "Ort {n} von {total}", smArrive: "Wir sind da: Standort prüfen", smArriveManual: "Wir sind da (ohne Standortprüfung)", smSimNote: "Demo: Die Ankunft ist simuliert; Hinweise, Fragen und Antworten sind echt.", smGpsNote: "Eine Standortprüfung auf irgendeinem Handy gilt für das ganze Team. Gesendet wird nur „angekommen“, nie eure Position.", smYourClues: "Deine Hinweise", smNoClues: "Hier hast du keinen Hinweis. Lies die Frage laut vor, sieh dich um und hilf dem Team, die Teile zusammenzusetzen.", smOffline: "{name} ist offline: Hinweise hier anzeigen", smBoard: "Team-Tafel", smBoardEmpty: "Noch nichts geteilt. Lest eure Hinweise laut vor oder tippt auf „Mit dem Team teilen“.", smSharedBy: "geteilt von {name}", smShared: "auf der Team-Tafel", smShare: "Mit dem Team teilen", smTakenFrom: "Hinweis von {name}", smKind_history: "Geschichte", smKind_visual: "Suche", smKind_architecture: "Architektur", smKind_interpretation: "Deutung", smArrivedGps: "Angekommen · Standort geprüft", smArrivedSim: "Angekommen · simuliert (Demo)", smArrivedManual: "Angekommen · ohne Standortprüfung bestätigt", smGpsDenied: "Der Standortzugriff ist nicht erlaubt. Ihr könnt die Ankunft trotzdem ohne Prüfung bestätigen.", smWrong: "Nicht ganz. Vergleicht eure Hinweise: Ihr braucht mehr als einen.", smRight: "Gelöst! ✓", smSolvedTitle: "Rätsel gelöst", smSolution: "Die Lösung", smConnect: "Wie eure Hinweise zusammenpassen", smStory: "Die ganze Geschichte", smRestart: "Von vorn", smFacts: "Wusstet ihr schon?", smFiction: "Die Notiz am Anfang des Abenteuers ist erfunden. Orte, Daten und Fakten sind echt und stammen aus den Quellen unten.", smPhotos: "Fotos (Wikimedia Commons)", smListen: "Anhören", smPause: "Pause", smRec: "Aufgenommene Erzählung.", smVoice: "Vorgelesen von der Stimme des Geräts (noch keine Aufnahme).", smNoVoice: "Dieses Gerät kann nicht vorlesen: Der ganze Text steht unten." });
Object.assign(window.WALKBCN_UI.it, { mpCooperative: "Cooperativo", mpCompHint: "Ognuno gioca per sé: vince chi è più veloce o fa più punti.", smDesc: "Shared Mystery: giocate in squadra. Ogni telefono riceve indizi diversi, quindi dovrete parlare, condividere e osservare per risolvere insieme un pezzo vero della storia di Barcellona.", smPick: "Scegli un'avventura", smMeta: "{n} luoghi + deduzione finale · circa {m} min", smDemoPlayers: "Giocatori nella demo", smDemoBanner: "DEMO · compagni e arrivi simulati · non si invia né si salva nulla", smViewAs: "Vedi la partita come:", smAllShare: "Tutti condividono gli indizi (simulato)", smFinalStep: "Deduzione finale", smTeam: "Squadra", smLeft: "è uscito", smNotebook: "Taccuino della squadra", smQ: "La domanda della squadra", smQHint: "Chiunque può rispondere per la squadra. Prima confrontate gli indizi: uno solo non basta.", smEndedUnsolved: "L'indagine è finita prima di risolvere il mistero.", smFictionTag: "Cornice narrativa: finzione · Luoghi e fatti: reali", smRules: "Come funziona: in ogni luogo ogni telefono mostra indizi diversi. Camminate insieme, confermate l'arrivo (basta un telefono), leggete gli indizi ad alta voce o metteteli sulla bacheca della squadra e rispondete insieme. Niente cronometro né classifica: vincete insieme.", smBegin: "Inizia l'indagine", smNew: "Nuovo nel taccuino:", smStep: "Luogo {n} di {total}", smArrive: "Ci siamo: verifica la posizione", smArriveManual: "Ci siamo (senza verificare la posizione)", smSimNote: "Demo: l'arrivo è simulato; indizi, domande e risposte sono quelli veri.", smGpsNote: "Una verifica della posizione su qualsiasi telefono vale per tutta la squadra. Si invia solo «arrivati», mai la vostra posizione.", smYourClues: "I tuoi indizi", smNoClues: "Qui non hai indizi. Leggi la domanda ad alta voce, guardati intorno e aiuta la squadra a mettere insieme i pezzi.", smOffline: "{name} è offline: mostra qui i suoi indizi", smBoard: "Bacheca della squadra", smBoardEmpty: "Ancora niente di condiviso. Leggete gli indizi ad alta voce o toccate «Condividi con la squadra».", smSharedBy: "condiviso da {name}", smShared: "sulla bacheca della squadra", smShare: "Condividi con la squadra", smTakenFrom: "Indizio di {name}", smKind_history: "Storia", smKind_visual: "Cerca", smKind_architecture: "Architettura", smKind_interpretation: "Interpretazione", smArrivedGps: "Arrivati · posizione verificata", smArrivedSim: "Arrivati · simulato (demo)", smArrivedManual: "Arrivati · confermato senza verificare la posizione", smGpsDenied: "La posizione non è consentita. Potete comunque confermare l'arrivo senza verificarla.", smWrong: "Non proprio. Confrontate gli indizi: ne serve più di uno.", smRight: "Risolto! ✓", smSolvedTitle: "Mistero risolto", smSolution: "La soluzione", smConnect: "Come si incastrano i vostri indizi", smStory: "La storia completa", smRestart: "Ricomincia", smFacts: "Lo sapevate?", smFiction: "La nota che apre l'avventura è finzione. Luoghi, date e fatti sono reali e provengono dalle fonti qui sotto.", smPhotos: "Foto (Wikimedia Commons)", smListen: "Ascolta", smPause: "Pausa", smRec: "Narrazione registrata.", smVoice: "Letto dalla voce del dispositivo (ancora nessuna registrazione).", smNoVoice: "Questo dispositivo non può leggere ad alta voce: il testo completo è qui sotto." });
Object.assign(window.WALKBCN_UI.zh, { mpCooperative: "合作", mpCompHint: "每人各自比赛：最快或得分最高者获胜。", smDesc: "共享谜案：组队游戏。每部手机收到不同的线索，你们需要交流、分享并仔细观察，一起解开巴塞罗那历史中的一个真实片段。", smPick: "选择一个冒险", smMeta: "{n} 个地点 + 最终推理 · 约 {m} 分钟", smDemoPlayers: "演示中的玩家人数", smDemoBanner: "演示 · 队友和到达均为模拟 · 不发送也不保存任何内容", smViewAs: "以此身份查看：", smAllShare: "所有人分享线索（模拟）", smFinalStep: "最终推理", smTeam: "队伍", smLeft: "已离开", smNotebook: "队伍笔记", smQ: "队伍的问题", smQHint: "任何人都可以代表队伍作答。先比较线索：只有一条是不够的。", smEndedUnsolved: "调查在谜案解开之前就结束了。", smFictionTag: "故事框架：虚构 · 地点与史实：真实", smRules: "玩法：在每个地点，每部手机显示不同的线索。一起步行，确认到达（一部手机即可），大声读出线索或把它们放到队伍公告板上，然后作为一个团队作答。没有计时，没有排名：大家一起赢。", smBegin: "开始调查", smNew: "笔记新增：", smStep: "第 {n} 个地点，共 {total} 个", smArrive: "我们到了：核验位置", smArriveManual: "我们到了（不核验位置）", smSimNote: "演示：到达为模拟；线索、问题和答案都是真实的。", smGpsNote: "任意一部手机核验一次位置即对全队有效。只发送“已到达”，从不发送你们的位置。", smYourClues: "你的线索", smNoClues: "这个地点你没有线索。大声读出问题，看看四周，帮助队伍把碎片拼起来。", smOffline: "{name} 已离线：在这里显示其线索", smBoard: "队伍公告板", smBoardEmpty: "还没有分享任何内容。大声读出线索，或点击“与队伍分享”。", smSharedBy: "由 {name} 分享", smShared: "已在队伍公告板上", smShare: "与队伍分享", smTakenFrom: "{name} 的线索", smKind_history: "历史", smKind_visual: "寻找", smKind_architecture: "建筑", smKind_interpretation: "解读", smArrivedGps: "已到达 · 位置已核验", smArrivedSim: "已到达 · 模拟（演示）", smArrivedManual: "已到达 · 未核验位置而确认", smGpsDenied: "未允许访问位置。你们仍可以在不核验的情况下确认到达。", smWrong: "不太对。比较一下线索：你们需要不止一条。", smRight: "解开了！✓", smSolvedTitle: "谜案已解", smSolution: "答案", smConnect: "你们的线索如何拼合", smStory: "完整的故事", smRestart: "重新开始", smFacts: "你们知道吗？", smFiction: "开启冒险的那张字条是虚构的。地点、日期和史实都是真实的，来自下方的资料。", smPhotos: "照片（维基共享资源）", smListen: "收听", smPause: "暂停", smRec: "录制的旁白。", smVoice: "由设备语音朗读（暂无录音）。", smNoVoice: "此设备无法朗读：完整文字在下方。" });
